    ('c5f11350-c167-5f5b-8480-2a2c73dad577', 'mermelada-de-albaricoque-koura-valley-800g', 'Mermelada de Albaricoque Koura Valley - 800 g', '', 45000, '800 g', true, '/products-brochure/mermelada-de-albaricoque-koura-valley-800g.webp', 'conservas'),
